// ADR-047 (S1, port plan §3): replacement of vendor packages/ui/src/i18n.ts in protect-ui.js (build-protect.mjs
// resolves every import of that file here). Same exports and semantics as the vendored helper, but messages come from
// the module's own ru/en catalog (locales/catalog.generated.json, generated by build-protect from the vendored
// _locales plus locales/{ru,en}.json) instead of chrome.i18n: the production UI chooses its language itself
// (storage.local 'ui-language-v1', 21 languages). The island host passes that language in; ru -> ru, every other
// production language -> en for full settings. The separate Firewall launcher
// overlay translates its navigation and real state labels in all 21 languages.

import CATALOG_JSON from '../locales/catalog.generated.json';
import FIREWALL_LAUNCHER_JSON from '../locales/firewall-launcher.json';
import FIREWALL_BRANDING_JSON from '../locales/firewall-branding.json';
import FINDINGS_JSON from '../locales/findings.json';
import { resolveMessage } from '../../../../vendor/protect-722fae8/packages/ui/src/view-models/message';
import type { Message, Translate } from '../../../../vendor/protect-722fae8/packages/ui/src/view-models/message';
import { fallbackMessage, formatEntry } from '../format-message';
import type { Catalog } from '../format-message';

export { fallbackMessage };

export type UiLocale = 'ru' | 'en';
export type LauncherLocale = keyof typeof FIREWALL_LAUNCHER_JSON;

const CATALOG = CATALOG_JSON as unknown as Readonly<Record<UiLocale, Catalog>>;
const FIREWALL_LAUNCHER = FIREWALL_LAUNCHER_JSON as Readonly<Record<LauncherLocale, Catalog>>;
const FIREWALL_ALIASES = FIREWALL_BRANDING_JSON.aliases as Readonly<Record<string, string>>;
const FIREWALL_BRANDING = FIREWALL_BRANDING_JSON.messages as Readonly<Record<UiLocale, Catalog>>;
const FINDINGS = FINDINGS_JSON as Readonly<Record<LauncherLocale, Catalog>>;

/** Production language id chosen in the production UI (null until the host passes one). */
let productionLocale: string | null = null;

/** Module language for a production language id: ru stays ru, every other language falls back to en. */
export function moduleLocaleOf(language: string | null | undefined): UiLocale {
  return typeof language === 'string' && language.toLowerCase().split(/[-_]/)[0] === 'ru' ? 'ru' : 'en';
}

/** Locale of the localized launcher only; this does not claim a full module translation. */
export function launcherLocaleOf(language: string | null | undefined): LauncherLocale {
  const normalized = typeof language === 'string' ? language.toLowerCase().replace(/-/g, '_') : '';
  const exact = (Object.keys(FIREWALL_LAUNCHER) as LauncherLocale[]).find(key => key.toLowerCase() === normalized);
  if (exact !== undefined) return exact;
  const base = normalized.split('_')[0];
  if (base === 'zh') return 'zh_CN';
  if (base === 'pt') return 'pt_BR';
  return Object.hasOwn(FIREWALL_LAUNCHER, base ?? '') ? base as LauncherLocale : 'en';
}

export function launcherDirectionOf(language: string | null | undefined): 'ltr' | 'rtl' {
  const locale = launcherLocaleOf(language);
  return locale === 'ar' || locale === 'ur' ? 'rtl' : 'ltr';
}

/** True when the production language has no module translation (the island shows English with a note). */
export function isFallbackLocale(language: string | null | undefined): boolean {
  return typeof language === 'string' && language !== 'ru' && language !== 'en';
}

/** Called by the island host on every render with the production uiLocale(). */
export function setProductionLocale(language: string | null): void {
  productionLocale = typeof language === 'string' && language.length > 0 && language.length <= 16 ? language : null;
}

export function currentProductionLocale(): string | null {
  return productionLocale;
}

function browserLanguage(): string | null {
  try {
    if (typeof chrome === 'undefined') return null;
    const api = (chrome as { i18n?: { getUILanguage?: () => string } }).i18n;
    const value = typeof api?.getUILanguage === 'function' ? api.getUILanguage() : null;
    return typeof value === 'string' ? value : null;
  } catch {
    return null;
  }
}

/** Locale of the module texts: the production choice, else the browser UI language (ru or en). */
export function uiLocale(): UiLocale {
  return moduleLocaleOf(productionLocale ?? browserLanguage());
}

function entryOf(key: string): Catalog[string] | undefined {
  const launcher = launcherLocaleOf(productionLocale ?? browserLanguage());
  const alias = Object.hasOwn(FIREWALL_ALIASES, key) ? FIREWALL_ALIASES[key] ?? key : key;
  if (Object.hasOwn(FINDINGS[launcher], key)) return FINDINGS[launcher][key];
  if (Object.hasOwn(FIREWALL_LAUNCHER[launcher], alias)) return FIREWALL_LAUNCHER[launcher][alias];
  if (Object.hasOwn(FIREWALL_BRANDING[uiLocale()], key)) return FIREWALL_BRANDING[uiLocale()][key];
  return CATALOG[uiLocale()][key] ?? CATALOG.en[key];
}

export const t: Translate = (key, subs) => {
  const entry = entryOf(key);
  return entry === undefined ? fallbackMessage(key, subs) : formatEntry(entry, subs);
};

export function applyDocumentLanguage(doc: Document): void {
  doc.documentElement.lang = uiLocale();
  doc.documentElement.dir = 'ltr';
}

/** Resolves a message descriptor (key + substitutions, possibly nested) through `t`. */
export function tm(message: Message): string {
  return resolveMessage(t, message);
}

/** Like `t` but null instead of the key when the catalog has no such message (free-form codes). */
export function tOptional(key: string): string | null {
  const entry = entryOf(key);
  return entry === undefined ? null : formatEntry(entry);
}

/** Number of messages per language (tests and the build report). */
export function catalogSize(): { ru: number; en: number } {
  return { ru: Object.keys(CATALOG.ru).length, en: Object.keys(CATALOG.en).length };
}
